def parse_expression(tokens):
    values = []
    ops = []
    i = 0

    while i < len(tokens):
        token = tokens[i]

        if token.isdigit() or '.' in token:
            values.append(float(token))
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                right = values.pop()
                left = values.pop()
                op = ops.pop()
                values.append(apply_op(left, right, op))
