                right = values.pop()
                left = values.pop()
                op = ops.pop()
                values.append(apply_op(left, right, op))
            ops.append(token)

        i += 1

    while ops:
        right = values.pop()
        left = values.pop()
        op = ops.pop()
        values.append(apply_op(left, right, op))

    return values[-1]


